issue.body:
#15151 changed `lpEncodeBacklen()` and `lpEncodeBacklenBytes()` to encode `element-tot-len` of 16383, 2097151 and 268435455 in one byte less. Both forms decode to the same value, e.g. 16383 is `7F FF` now and was `00 FF FF` up to 8.6. Before the change both functions used `<`, so writing and reading agreed.

`lpEncodeBacklenBytes()` is also used to read existing entries: `lpSkip()`, `lpSkipPrev()` and `lpValidateNext()` compute the width of the field from the entry length instead of reading it:

```c
static inline unsigned char *lpSkip(unsigned char *p) {
    unsigned long entrylen = lpCurrentEncodedSizeUnsafe(p);
    entrylen += lpEncodeBacklenBytes(entrylen);   /* 2 for 16383; data written by 8.6 has 3 */
    p += entrylen;
```

So on a listpack written before 8.8 with such an entry, the forward walk stops one byte early, inside `element-tot-len`. Deep validation rejects the listpack, and `lpFirst()`/`lpNext()` fail `assert(lpValidateNext(lp, &p, lpbytes))`.

The reverse also holds: the code before #15151 rejects the 2-byte form that 8.8+ writes.

### Reproducer

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "listpack.h"

/* Stubs for the parts of the server listpack.c links against. */
void *zmalloc(size_t n) { return malloc(n); }
void *zmalloc_usable(size_t n, size_t *u) { *u = n; return malloc(n); }
void *zrealloc_usable(void *p, size_t n, size_t *u, size_t *o) { (void)o; *u = n; return realloc(p, n); }
void zfree(void *p) { free(p); }
int ll2string(char *s, size_t len, long long v) { return snprintf(s, len, "%lld", v); }
void _serverAssert(const char *e, const char *f, int l) { printf("ASSERTION FAILED: %s (%s:%d)\n", e, f, l); exit(1); }

int main(void) {
    /* One 16378-byte string (entry size 16383) with element-tot-len
     * encoded in 3 bytes, as Redis <= 8.6 writes it. */
    enum { SLEN = 16378, SIZE = 6 + 5 + SLEN + 3 + 1 };
    static unsigned char lp[SIZE] = { SIZE & 0xff, SIZE >> 8, 0, 0, 1, 0,
                                      0xF0, SLEN & 0xff, SLEN >> 8, 0, 0 };
    memset(lp + 11, 'a', SLEN);
    memcpy(lp + 11 + SLEN, "\x00\xFF\xFF\xFF", 4);   /* 16383 in 3 bytes, end */

    printf("deep validation: %s\n", lpValidateIntegrity(lp, SIZE, 1, NULL, NULL) ? "ok" : "rejected");
    lpFirst(lp);
    printf("lpFirst: ok\n");
    return 0;
}
```

Reported by Dilshod Urazov (GenProof)
